import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

function createTestInvoices() {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const inv1Issued = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'ICON-SET', qty: 5 }],
    terms: 'NET30',
  }).value;
  const inv2Issued = issueInvoice(inv2, [inv1Issued.number]).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'HOST-MONTH', qty: 2 }],
    terms: 'NET14',
  }).value;
  const inv3Issued = issueInvoice(inv3, [inv1Issued.number, inv2Issued.number]).value;

  return [inv1Issued, inv2Issued, inv3Issued];
}

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-09-10');

  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices past their due date', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-09-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoices[0].number);
});

test('overdueInvoices excludes invoices on their due date', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-09-15');

  assert.equal(result.length, 0);
});

test('overdueInvoices includes all overdue invoices', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-10-20');

  assert.equal(result.length, 3);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-10-20');

  assert.equal(result[0].daysOverdue > result[1].daysOverdue, true);
  assert.equal(result[0].number, invoices[0].number);
  assert.equal(result[1].number, invoices[1].number);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-09-30');

  const overdue = result.find((r) => r.number === invoices[0].number);
  assert.equal(overdue.daysOverdue, 15);
});

test('overdueInvoices includes invoice fields', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-10-20');

  const invoice = result[0];
  assert('number' in invoice);
  assert('customerId' in invoice);
  assert('dueDate' in invoice);
  assert('daysOverdue' in invoice);
  assert('due' in invoice);
});

test('overdueInvoices excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const invoices = [draft, ...createTestInvoices()];
  const result = overdueInvoices(invoices, '2026-10-20');

  assert.equal(result.length, 3);
  assert(!result.some((r) => r.number === undefined));
});

test('overdueInvoices excludes fully paid invoices', () => {
  const invoices = createTestInvoices();
  const { total } = invoiceTotals(invoices[0]);
  const paidResult = recordPayment(invoices[0], {
    amount: total,
    date: '2026-09-20',
  });

  if (!paidResult.ok) {
    throw new Error(`Failed to record payment: ${paidResult.error}`);
  }

  const paid = paidResult.value;
  const mixed = [paid, invoices[1], invoices[2]];
  const result = overdueInvoices(mixed, '2026-10-20');

  assert.equal(result.length, 2);
});

test('overdueInvoices includes partially paid invoices', () => {
  const invoices = createTestInvoices();
  const partial = recordPayment(invoices[0], {
    amount: 10000,
    date: '2026-09-20',
  }).value;

  const mixed = [partial, invoices[1], invoices[2]];
  const result = overdueInvoices(mixed, '2026-10-20');

  assert.equal(result.length, 3);
  const partialInvoice = result.find((r) => r.number === partial.number);
  assert(partialInvoice.due > 0);
  const { total } = invoiceTotals(partial);
  assert(partialInvoice.due < total);
});

test('overdueInvoices includes correct due amount', () => {
  const invoices = createTestInvoices();
  const paymentAmount = 5000;
  const partial = recordPayment(invoices[0], {
    amount: paymentAmount,
    date: '2026-09-20',
  }).value;

  const result = overdueInvoices([partial, invoices[1], invoices[2]], '2026-10-20');

  const { total } = invoiceTotals(partial);
  const partialOverdue = result.find((r) => r.number === partial.number);
  assert(partialOverdue.due > 0);
  assert(partialOverdue.due < total);
  assert.equal(partialOverdue.due, total - paymentAmount);
});

test('overdueInvoices with multiple customers', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-10-20');

  const customers = new Set(result.map((r) => r.customerId));
  assert(customers.has('C-001'));
  assert(customers.has('C-002'));
});

test('overdueInvoices with empty invoice list', () => {
  const result = overdueInvoices([], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices preserves invoice details', () => {
  const invoices = createTestInvoices();
  const result = overdueInvoices(invoices, '2026-10-20');

  result.forEach((overdue) => {
    const original = invoices.find((inv) => inv.number === overdue.number);
    assert.equal(overdue.customerId, original.customerId);
    assert.equal(overdue.dueDate, original.dueDate);
  });
});

test('vatSummary groups by VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  const rate21 = result.find((r) => r.rate === 21);
  const rate9 = result.find((r) => r.rate === 9);
  assert(rate21);
  assert(rate9);
});

test('vatSummary calculates base correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  const rate21 = result.find((r) => r.rate === 21);
  assert.equal(rate21.base, 17000);
});

test('vatSummary calculates VAT correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  const rate21 = result.find((r) => r.rate === 21);
  const expectedVat = 17000 * 21 / 100;
  assert.equal(rate21.vat, expectedVat);
});

test('vatSummary accounts for discounts in base', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  const rate21 = result.find((r) => r.rate === 21);
  const expectedBase = 17000 - 1700;
  assert.equal(rate21.base, expectedBase);
});

test('vatSummary sorts by rate descending', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(draft, []).value;

  const result = vatSummary([draft, issued]);

  assert.equal(result.length, 1);
  const rate21 = result.find((r) => r.rate === 21);
  assert(rate21.vat > 0);
});

test('vatSummary includes paid invoices', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(draft, []).value;
  const { total } = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: total, date: '2026-10-08' }).value;

  const result = vatSummary([paid]);

  assert.equal(result.length, 1);
  const rate21 = result.find((r) => r.rate === 21);
  assert(rate21.vat > 0);
});

test('vatSummary includes partially paid invoices', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(draft, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-08' }).value;

  const result = vatSummary([partial]);

  assert.equal(result.length, 1);
  const rate21 = result.find((r) => r.rate === 21);
  assert(rate21.vat > 0);
});

test('vatSummary with multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  }).value;
  const issued2 = issueInvoice(inv2, [issued1.number]).value;

  const result = vatSummary([issued1, issued2]);

  const rate21 = result.find((r) => r.rate === 21);
  const rate9 = result.find((r) => r.rate === 9);
  assert(rate21.base > 0);
  assert(rate9.base > 0);
});

test('vatSummary with VAT exempt products', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  const rate0 = result.find((r) => r.rate === 0);
  assert(rate0);
  assert.equal(rate0.vat, 0);
});

test('vatSummary with empty invoice list', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary returns entry structure with all fields', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  result.forEach((entry) => {
    assert('rate' in entry);
    assert('base' in entry);
    assert('vat' in entry);
    assert(typeof entry.rate === 'number');
    assert(typeof entry.base === 'number');
    assert(typeof entry.vat === 'number');
  });
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const fee = lateFee(issued, '2026-10-21');
  assert.equal(fee, 0);
});

test('lateFee returns 0 on the due date', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const fee = lateFee(issued, issued.dueDate);
  assert.equal(fee, 0);
});

test('lateFee calculates 0.04% per day for overdue invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const { total } = invoiceTotals(issued);

  const asOf = '2026-10-28';
  const fee = lateFee(issued, asOf);
  const daysOverdue = 7;
  const expectedFee = Math.round(total * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee uses balanceDue for partially paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const { total } = invoiceTotals(issued);
  const paymentAmount = 5000;
  const partial = recordPayment(issued, { amount: paymentAmount, date: '2026-10-15' }).value;

  const asOf = '2026-10-28';
  const fee = lateFee(partial, asOf);
  const daysOverdue = 7;
  const balanceDue = total - paymentAmount;
  const expectedFee = Math.round(balanceDue * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee returns 0 for fully paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const { total } = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: total, date: '2026-10-15' }).value;

  const fee = lateFee(paid, '2026-10-22');
  assert.equal(fee, 0);
});

test('lateFee increases with more days overdue', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const fee1 = lateFee(issued, '2026-10-22');
  const fee7 = lateFee(issued, '2026-10-28');
  assert(fee7 > fee1);
});

test('lateFee with 30-day terms', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const { total } = invoiceTotals(issued);

  const fee = lateFee(issued, '2026-11-20');
  const daysOverdue = 21;
  const expectedFee = Math.round(total * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee rounds correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const fee = lateFee(issued, '2026-10-22');
  assert(Number.isInteger(fee));
  assert(fee >= 0);
});

test('lateFee returns 0 when no dueDate on invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  issued.dueDate = undefined;

  const fee = lateFee(issued, '2026-10-22');
  assert.equal(fee, 0);
});
